fn extract_rear_chars(l: &Vec<Vec<char>>) -> Vec<char> {
    // Pre-allocate a vector with the same length as the outer vector
    let mut r = Vec::with_capacity(l.len());
    // For each inner vector, push its last character onto r
    for inner in l.iter() {
        // We can safely unwrap because each inner vector is guaranteed non-empty
        r.push(*inner.last().unwrap());
    }
    r
}

